function Gauge({ value }) {
  const cx = 100, cy = 100, r = 76;
  const tier = riskTier(value);
  const valueAngle = 180 - (value / 100) * 180;
  const trackPath = describeArc(cx, cy, r, 180, 0);
  const valuePath = describeArc(cx, cy, r, 180, valueAngle);
  const tip = polarToCartesian(cx, cy, r, valueAngle);
  const gradientMap = {
    emerald: { a: '#059669', b: '#34d399' },
    amber: { a: '#b45309', b: '#fbbf24' },
    red: { a: '#9f1239', b: '#fb7185' }
  };
  const solidMap = { emerald: '#34d399', amber: '#fbbf24', red: '#fb7185' };
  const grad = gradientMap[tier.color];
  const solid = solidMap[tier.color];

  return (
    <svg viewBox="0 0 200 116" className="w-full max-w-sm mx-auto block">
      <defs>
        <filter id="hh-glow" x="-60%" y="-60%" width="220%" height="220%">
          <feGaussianBlur stdDeviation="4.5" result="b" />
          <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
        <linearGradient id="hh-arcgrad" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor={grad.a} />
          <stop offset="100%" stopColor={grad.b} />
        </linearGradient>
        <linearGradient id="hh-numgrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="100%" stopColor="#c4c4c9" />
        </linearGradient>
      </defs>
      <path d={trackPath} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="8" strokeLinecap="round" />
      <path d={valuePath} fill="none" stroke="url(#hh-arcgrad)" strokeWidth="8" strokeLinecap="round" filter="url(#hh-glow)" style={{ transition: 'all 0.3s ease' }} />
      <circle cx={tip.x} cy={tip.y} r="5" fill={solid} filter="url(#hh-glow)" />
      <text x={cx} y={cy - 27} textAnchor="middle" fontFamily="ui-monospace, monospace" fontWeight="600" fontSize="32" fill="url(#hh-numgrad)">{Math.round(value)}</text>
      <text x={cx} y={cy - 9} textAnchor="middle" fontFamily="ui-sans-serif, system-ui" fontSize="10" fill={solid} letterSpacing="0.5">{tier.label}</text>
    </svg>
  );
}

